<div class="row g-4 debt-payoff-calculator-rebuilt"><div class="col-lg-12"><div class="calculator-card"><div class="calculator-body"><div class="row g-3"><div class="col-md-6"><label class="form-label-custom">Current Balance ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="dp-bal" class="form-control form-control-lg" value="15000" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Interest Rate (%)</label><div class="input-group"><input type="number" id="dp-rate" class="form-control form-control-lg" value="18" min="0"><span class="input-group-text bg-light fw-bold">%</span></div></div><div class="col-md-6"><label class="form-label-custom">Minimum Payment ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="dp-min" class="form-control form-control-lg" value="300" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Extra Payment ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="dp-extra" class="form-control form-control-lg" value="200" min="0"></div></div></div></div></div></div><div class="col-lg-12"><div class="output-card-themed" style="--tool-hue:160;--tool-color:#10b981;--tool-bg:rgba(0,0,0,.02);"><div class="output-hero"><span class="output-hero-label">Debt Payoff Calculator</span><div class="output-hero-value" id="debt-val">—</div><span class="output-hero-unit" id="debt-st">—</span></div><div class="row g-3 mt-3"><div class="col-md-3"><div class="stat-card" style="border-color:#10b981;background:rgba(0,0,0,.02);"><span class="stat-card-label">PAYOFF TIME</span><span class="stat-card-value" style="color:#10b981" id="dp-months">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#ef4444;background:rgba(0,0,0,.02);"><span class="stat-card-label">TOTAL INTEREST</span><span class="stat-card-value" style="color:#ef4444" id="dp-total-i">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#22c55e;background:rgba(0,0,0,.02);"><span class="stat-card-label">INTEREST SAVED</span><span class="stat-card-value" style="color:#22c55e" id="dp-saved">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#3b82f6;background:rgba(0,0,0,.02);"><span class="stat-card-label">MONTHS FASTER</span><span class="stat-card-value" style="color:#3b82f6" id="dp-faster">—</span></div></div></div><div class="mt-4" id="debt-ins"></div><div class="row g-2 mt-4"><div class="col-md-4"><button class="btn d-block mx-auto btn-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="debt-cp"><i class="fas fa-copy me-2"></i>Copy Summary</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="debt-rs"><i class="fas fa-rotate-left me-2"></i>Reset</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-primary py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="debt-cb"><i class="fas fa-calculator me-2"></i>Calculate</button></div></div></div></div></div>
<script>document.addEventListener("DOMContentLoaded",function(){const $=id=>document.getElementById(id);function fmt(v){return"$"+Math.round(v).toLocaleString();}function calc(){const bal=parseFloat($("dp-bal").value)||0,rate=(parseFloat($("dp-rate").value)||0)/100/12,min=parseFloat($("dp-min").value)||1,extra=parseFloat($("dp-extra").value)||0;function payoff(b,r,p){let m=0,ti=0;while(b>0&&m<600){const i=b*r;ti+=i;b=b+i-p;m++;if(b<0)b=0;}return{m,ti};}const base=payoff(bal,rate,min);const fast=payoff(bal,rate,min+extra);$("debt-val").textContent=fast.m+" months";$("dp-months").textContent=fast.m+" mo";$("dp-total-i").textContent=fmt(fast.ti);$("dp-saved").textContent=fmt(base.ti-fast.ti);$("dp-faster").textContent=(base.m-fast.m)+" mo";$("debt-st").textContent=extra>0?"ACCELERATED":"MINIMUM ONLY";$("debt-st").style.color=extra>0?"#22c55e":"#f59e0b";let ins=[];ins.push("Payoff in <strong>"+fast.m+" months</strong> with "+fmt(min+extra)+"/mo payments.");if(extra>0)ins.push("Extra "+fmt(extra)+"/mo saves <strong>"+fmt(base.ti-fast.ti)+"</strong> in interest and "+(base.m-fast.m)+" months.");$("debt-ins").innerHTML='<h6 class="fw-bold mb-2"><i class="fas fa-lightbulb me-2 text-warning"></i>Analysis</h6><ul class="list-unstyled mb-0 small">'+ins.map(x=>'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+'</li>').join("")+'</ul>';}['dp-bal','dp-rate','dp-min','dp-extra'].forEach(id=>$(id).addEventListener("input",calc));$("debt-cb").addEventListener("click",calc);$("debt-cp").addEventListener("click",function(){navigator.clipboard.writeText("Debt Payoff Calculator: "+$("debt-val").textContent).then(()=>{const o=this.innerHTML;this.innerHTML='<i class="fas fa-check me-2"></i>Copied!';setTimeout(()=>this.innerHTML=o,2e3);});});$("debt-rs").addEventListener("click",()=>{$("dp-bal").value=15000;$("dp-rate").value=18;$("dp-min").value=300;$("dp-extra").value=200;calc();});calc();});</script>
<style>.debt-payoff-calculator-rebuilt .calculator-card{background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:2rem;box-shadow:0 4px 24px rgba(0,0,0,.04)}.debt-payoff-calculator-rebuilt .calculator-header{display:flex;align-items:center;gap:1.25rem;margin-bottom:2rem}.debt-payoff-calculator-rebuilt .calculator-header h4{margin:0;font-weight:700;font-size:1.1rem;color:#1e293b}.debt-payoff-calculator-rebuilt .calculator-header p{margin:0;font-size:.85rem;color:#64748b}.debt-payoff-calculator-rebuilt .tool-icon-circle{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;flex-shrink:0}.debt-payoff-calculator-rebuilt .form-label-custom{font-size:.75rem;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.8px;margin-bottom:.4rem;display:block}</style>